def f(g):
    import collections
    cnt=collections.Counter(x for r in g for x in r)
    bg=max(cnt,key=lambda c:cnt[c])
    pts=[(i,j) for i,r in enumerate(g) for j,x in enumerate(r) if x!=bg]
    if not pts: return [r[:] for r in g]
    rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    out=[r[:] for r in g]
    for j in range(c0,c1+1):
        for i in (r0,r1):
            if out[i][j]==bg: out[i][j]=2
    for i in range(r0,r1+1):
        for j in (c0,c1):
            if out[i][j]==bg: out[i][j]=2
    return out
